package com.aicharacter.v3;
import android.app.AlarmManager;import android.app.PendingIntent;import android.content.Context;import android.content.Intent;import java.util.Calendar;
public final class ProactiveScheduler {private ProactiveScheduler(){}public static void scheduleApproximate(Context c,WorldState s){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,ProactiveReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(c,191,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(!s.proactiveEnabled){am.cancel(pi);return;}long base=2L*3600000;long relation=(long)Math.max(0,(24-s.relationship.attachment)*5*60000L);long trigger=System.currentTimeMillis()+base+relation;am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,trigger,pi);}public static boolean isQuietHour(WorldState s){return QuietHoursPolicy.isQuiet(s,System.currentTimeMillis());}public static boolean isQuietHourAt(WorldState s,long time){return QuietHoursPolicy.isQuiet(s,time);}}
